<?php
use App\Models\User;use Database\Seeders\RolePermissionSeeder;use Illuminate\Support\Facades\Hash;use Inertia\Testing\AssertableInertia as Assert;
beforeEach(fn()=> $this->seed(RolePermissionSeeder::class));
it('allows a superadmin to create and manage a user',function(){$admin=User::factory()->create()->assignRole('superadmin');$this->actingAs($admin)->post(route('users.store'),['name'=>'Agent EDSP','email'=>'agent@edsp.mg','role'=>'secretaire','password'=>'MotDePasse-2026','password_confirmation'=>'MotDePasse-2026'])->assertRedirect(route('users.index'));$user=User::whereEmail('agent@edsp.mg')->firstOrFail();expect($user->hasRole('secretaire'))->toBeTrue()->and(Hash::check('MotDePasse-2026',$user->password))->toBeTrue();$this->patch(route('users.update',$user),['name'=>$user->name,'email'=>$user->email,'role'=>'secretaire','is_active'=>false,'password'=>'','password_confirmation'=>''])->assertRedirect(route('users.index'));expect($user->refresh()->is_active)->toBeFalse();});
it('protects the last superadmin',function(){$admin=User::factory()->create()->assignRole('superadmin');$this->actingAs($admin)->patch(route('users.update',$admin),['name'=>$admin->name,'email'=>$admin->email,'role'=>'secretaire','is_active'=>true])->assertSessionHasErrors('role');});
it('denies user management to secretaries',function(){$user=User::factory()->create()->assignRole('secretaire');$this->actingAs($user)->get(route('users.index'))->assertForbidden();});
it('deletes only users without operational history',function(){$admin=User::factory()->create()->assignRole('superadmin');$user=User::factory()->create()->assignRole('secretaire');$this->actingAs($admin)->delete(route('users.destroy',$user))->assertRedirect(route('users.index'));expect(User::find($user->id))->toBeNull();$this->delete(route('users.destroy',$admin))->assertSessionHasErrors('user');});
